const gradeWord=(w,b,c,allowBlankKanji=false)=>{const bOk=clean(b)===clean(w.kana),writtenC=String(c??'').normalize('NFKC').trim();const cOk=w.c==='X'?(/^[xX×]$/.test(writtenC)||(allowBlankKanji&&writtenC==='')):clean(c)===clean(w.c);return{bOk,cOk,score:(Number(bOk)+Number(cOk))*.5};};
const shuffle=a=>{const out=[...a];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]];}return out;};
function shuffledTokens(s){let ids=shuffle(s.tokens.map((_,i)=>i));if(ids.map(i=>s.tokens[i]).join('')===s.tokens.join(''))ids.push(ids.shift());return ids;}
const wordBy=id=>WORDS.find(w=>w.id===id);const sentenceBy=id=>SENTENCES.find(s=>s.id===id);const patternBy=id=>PATTERNS.find(p=>p.id===id);
function gradeSentence(s,chosen){const answer=rebuildText(chosen.map(i=>s.tokens[i]).join(''));if(chosen.length!==s.tokens.length)return false;if(answer===rebuildText(s.tokens.join('')))return true;if(s.pattern==='p12'){const alternate=[...s.tokens];[alternate[2],alternate[5]]=[alternate[5],alternate[2]];return answer===rebuildText(alternate.join(''));}return false;}
