const activeWordIds=new Set(WORDS.map(w=>w.id));for(const type of ['words','matches','hiraganaMatches','kanjiWriting','vocabularyRebuild'])for(const id of Object.keys(progress[type]))if(!activeWordIds.has(id))delete progress[type][id];
let mock=saved.contentRevision===CONTENT_REVISION?saved.mock||null:null;if(mock&&(!mock.a?.every(x=>wordBy(x.id))||!mock.b?.every(x=>sentenceBy(x.id))))mock=null;
const state={learningScopes:saved.learningScopes||{},learningReturn:null,numberBrowse:saved.numberSelection?.browse||(saved.numberSelection?.chapter&&!['all','general'].includes(saved.numberSelection.chapter)?'chapter':saved.numberSelection?.type&&saved.numberSelection.type!=='all'?'category':'all'),numberPage:0,numberType:restoredNumberScope(saved).type,numberChapter:restoredNumberScope(saved).chapter,numberRound:null,language:saved.language==='en'?'en':'zh-Hant',activity:null,dialogueBrowse:'all',dialogueChapter:1,dialogueCategory:'introductions',view:'home',writeMenu:'main',writeSet:null,vocabularyMenu:'main',vocabularySet:null,vocabularyContentKey:'all',handwritingMenu:'main',handwritingSet:null,filter:{ch:['all'],group:'all',status:'all',kana:'all',...saved.practiceFilters},pattern:'all',round:null,search:'',modal:false,navOpen:false,confirmReset:false};
