function breadcrumbItems(){const section=learningSection();return [{label:'Kotoba',view:'home'},...(state.view==='home'?[]:[{label:translateText(STUDY_MODES.find(m=>m.id===section)?.label||'Vocabulary'),view:section}])];}
function learningSection(){if(['write','vocabulary-content','vocabulary-rebuild','write-menu'].includes(state.view))return state.learningReturn==='bank'?'bank':'vocabulary-menu';if(['sentences','sentence-menu'].includes(state.view))return 'grammar';if(state.view==='activity')return state.activity?.scope?.learningHome||'pictures';if(state.view==='exam-practice')return state.learningReturn||'mixed';if(state.view==='number-game')return 'number-menu';if(state.view==='kanji-writing')return 'handwriting-menu';if(state.view==='mock-menu')return 'mock';return state.view;}
