function save(){try{localStorage.setItem(STORAGE,JSON.stringify({progress,mock,learningScopes:state.learningScopes,learningSchema:3,practiceFilters:state.filter,contentRevision:CONTENT_REVISION,language:state.language,numberSelection:{browse:state.numberBrowse,type:state.numberType,chapter:state.numberChapter}}));}catch{toast('Progress could not be saved in this browser. You can still practise.');}}
function record(type,id,ok){if(typeof exLegacyRecord==='function')exLegacyRecord(type,id,ok);const p=progress[type][id]||{wins:0,attempts:0,misses:0};p.attempts++;p.wins=ok?p.wins+1:0;if(!ok)p.misses++;p.last=ok;progress[type][id]=p;save();}
function status(id,type='words'){const p=progress[type][id];return !p?'New':p.wins>=2?'Secure':p.last?'Recalled':'Review';}
function secure(type){return Object.values(progress[type]).filter(p=>p.wins>=2).length;}
