function scopeModal(){return `<div class="modal-backdrop" data-action="closeBackdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="scope-title">${luluSectionArt('about')}<h2 id="scope-title">${nL('Learning & practice','學習與練習')}</h2><p>${nL('Choose one or more chapters, a content group and a topic, then choose a practice method. Playable counts exclude readings that still need checking.','先選一課或多課、組別與主題，再選練習方式。待確認讀音不列入可練習數量。')}</p><p>${nL('Timed practice covers Chapters 1–2: 15 minutes and 20 points. Mixed practice combines existing skills for 20 points.','計時練習涵蓋第1–2課：15分鐘、20分。綜合練習結合已有技能，共20分。')}</p><p>${nL('Progress is saved in this browser. Handwriting is self-assessed.','進度儲存在此瀏覽器。手寫採用自我評估。')}</p>${button('Close','closeScope','primary')}</section></div>`;}

function home(){
  const secured=VOCABULARY_WORDS.filter(word=>(progress.words[word.id]?.wins||0)>=2).length,tried=Object.keys(progress.words).filter(id=>VOCABULARY_WORD_IDS.has(id)).length;
  const patternsDone=PATTERNS.filter(p=>SENTENCES.filter(s=>s.pattern===p.id).every(s=>(progress.sentences[s.id]?.wins||0)>=1)).length;
  return `<section class="overview-intro"><div class="lulu-welcome">${luluSectionArt('home')}${header('Choose your practice.','Choose a mode to practise vocabulary and sentence patterns from Chapters 1–6.')}</div>${navigation('overview-nav')}</section><section class="overview-progress" aria-labelledby="progress-title"><div class="section-head"><h2 id="progress-title">Your progress</h2><span class="small muted">Saved in this browser</span></div>${luluProgressArt()}<div class="stats overview-stats"><div class="stat"><div class="stat-value">${tried}<span class="stat-total"> / ${VOCABULARY_WORDS.length}</span></div><div class="stat-label">Words practised</div><div class="overview-meter" aria-hidden="true"><span style="width:${100*tried/VOCABULARY_WORDS.length}%"></span></div><p class="stat-detail">${secured} secure · two correct answers in a row</p></div><div class="stat"><div class="stat-value">${patternsDone}<span class="stat-total"> / ${PATTERNS.length}</span></div><div class="stat-label">Sentence groups covered</div><div class="overview-meter" aria-hidden="true"><span style="width:${100*patternsDone/PATTERNS.length}%"></span></div><p class="stat-detail">All sentences in a group answered correctly</p></div><div class="stat"><div class="stat-value">${progress.best===null?'—':progress.best}<span class="stat-total"> / 20</span></div><div class="stat-label">Best timed practice</div><p class="stat-detail">15 minutes · 10 words + 5 sentences</p></div></div></section>`;
}
function wordSetMenu(mode){
  const hiragana=mode==='vocabulary-rebuild',handwriting=mode==='kanji-writing',rebuilding=hiragana,prefix=wordModePrefix(mode),section=state[`${prefix}Menu`],words=handwriting?WORDS.filter(w=>hasKanji(w)&&wordGameReady(w)):VOCABULARY_WORDS;
  const categories=(handwriting?VOCAB_CATEGORIES:VOCABULARY_CATEGORIES).filter(category=>words.some(w=>vocabularySection(w)===category.id));
  const action=rebuilding?'Start rebuilding':handwriting?'Start drawing':'Start recall',back='';
  if(section==='chapter')return header('Choose a chapter.',hiragana?'Rebuild vocabulary readings from one chapter.':handwriting?'Draw the kanji from one chapter.':'Recall vocabulary from one chapter.')+back+`<section class="mode-grid two-modes">${CHAPTERS.map(ch=>activityCard(chapterLabel(ch),hiragana?'Rebuild vocabulary readings from this chapter.':handwriting?'Draw the kanji from this chapter.':'Recall the words from this chapter.',`${words.filter(w=>inChapter(w,ch)).length} forms`,`data-${prefix}-set="chapter-${ch}"`,'',action,'chapters')).join('')}</section>`;
  if(section==='category')return header('Choose a category.',hiragana?'Rebuild vocabulary readings from one group.':handwriting?'Draw the kanji from one group.':'Recall vocabulary from one group.')+back+`<section class="mode-grid category-grid">${categories.map(category=>activityCard(category.label,category.description,`${words.filter(w=>vocabularySection(w)===category.id).length} forms`,`data-${prefix}-set="category-${category.id}"`,'',action,category.id)).join('')}</section>`;
  return header(hiragana?'Choose vocabulary to rebuild.':handwriting?'Choose kanji to practise.':'Choose vocabulary to recall.',hiragana?'Rebuild hiragana readings, or focus on one chapter or category.':handwriting?'Practise handwriting with all kanji words, one chapter or one category.':'Practise every word, or focus on one chapter or category.')+`<section class="mode-grid">${activityCard('All words',hiragana?'Rebuild the hiragana reading for every vocabulary form.':handwriting?'Draw all taught kanji forms.':'Recall every vocabulary form.',`${words.length} forms`,`data-${prefix}-set="all"`,'',action,'bank')}${activityCard('By chapter','Choose a chapter from 1 to 6.','6 chapters',`data-${prefix}-menu="chapter"`,'mode-yellow','Choose chapter','chapters')}${activityCard('By category','Choose a word group.',`${categories.length} groups`,`data-${prefix}-menu="category"`,'mode-blue','Choose category','categories')}</section>`;
}
