function handwritingMenu(){return wordSetMenu('kanji-writing');}
function selectedWordSet(mode){return ['write','vocabulary-rebuild','kanji-writing'].includes(mode)?state[`${wordModePrefix(mode)}Set`]:null;}
function startWordPractice(mode,ids,label,key=null){if(!['write','vocabulary-rebuild','kanji-writing'].includes(mode))return;const allowed=ids.filter(id=>!!wordBy(id)&&(mode==='kanji-writing'?hasKanji(wordBy(id))&&wordGameReady(wordBy(id)):VOCABULARY_WORD_IDS.has(id)));rememberPage();state[`${wordModePrefix(mode)}Set`]={ids:allowed,label,key};if(mode!=='kanji-writing'&&key&&vocabularyStudySet(key))state.vocabularyContentKey=key;state.view=mode;begin(mode,shuffle(allowed));render();window.scrollTo({top:0,behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
function startWriteWords(ids,label){startWordPractice('write',ids,label);}
function startWordSet(mode,key){if(key.startsWith('category-')){const migrated=migrateCategory(key.slice(9));key=migrated==='all'?'all':'category-'+migrated;}if(!['write','vocabulary-rebuild','kanji-writing'].includes(mode))return;let words=mode==='kanji-writing'?WORDS.filter(w=>hasKanji(w)&&wordGameReady(w)):VOCABULARY_WORDS,label;if(key==='all')label='All words';else if(/^chapter-[1-6]$/.test(key)){const ch=Number(key.slice(-1));words=words.filter(w=>inChapter(w,ch));label=chapterLabel(ch);}else{const id=key.startsWith('category-')?key.slice(9):'',category=VOCAB_CATEGORIES.find(c=>c.id===id);if(!category)return;words=words.filter(w=>vocabularySection(w)===id);label=category.label;}if(words.length)startWordPractice(mode,words.map(w=>w.id),label,key);}
function startWriteSet(key){startWordSet('write',key);}
function filters(sentence=false,hideKana=false){
 const mode=sentence?'sentences':state.view,source=sentence?SENTENCES:WORDS.filter(w=>wordGameReady(w)&&(mode!=='kanji-writing'||hasKanji(w))),chapters=CHAPTERS.filter(ch=>source.some(w=>matchesChapters(w,[ch])));
 state.filter.ch=normalizeChapters(state.filter.ch,chapters);const scoped=source.filter(w=>matchesChapters(w,state.filter.ch));
 const content=sentence?[['all',translateText('All sentence groups')],...PATTERNS.filter(p=>scoped.some(w=>w.pattern===p.id)).map(p=>[p.id,translateText(p.title)])]:[['all',translateText('All categories')],...VOCAB_CATEGORIES.filter(c=>scoped.some(w=>vocabularySection(w)===c.id)).map(c=>[c.id,translateText(c.label)])];
 if(!content.some(([id])=>id===(sentence?state.pattern:state.filter.group))){if(sentence)state.pattern='all';else state.filter.group='all';}
 return `<div class="learning-filters">${filterChips('legacy',mode,'ch',nL('Chapters','課次'),chapterChipOptions(chapters),state.filter.ch,true)}${filterChips('legacy',mode,sentence?'pattern':'group',translateText(sentence?'Sentence pattern':'Word category'),content,sentence?state.pattern:state.filter.group)}${filterChips('legacy',mode,'status',translateText('Practice selection'),[['all',translateText('All items')],['review',translateText('Needs practice')],['new',translateText('Not tried yet')]],state.filter.status)}${!sentence&&!hideKana?filterChips('legacy',mode,'kana',translateText('First hiragana'),[['all',translateText('Any first hiragana')],...HIRAGANA_KEYS.filter(([k])=>scoped.some(w=>hiraganaInitial(w)===k)).map(([k,r])=>[k,`${k} · ${r}`])],state.filter.kana||'all'):''}</div>`;
}

function pool(mode,ignoreKana=false){const sentence=mode==='sentences';return(sentence?SENTENCES:['write','vocabulary-rebuild'].includes(mode)?VOCABULARY_WORDS:WORDS).filter(x=>{if(['write','vocabulary-rebuild','kanji-writing'].includes(mode)&&!wordGameReady(x))return false;if(mode==='kanji-writing'&&!hasKanji(x))return false;if(!matchesChapters(x,state.filter.ch))return false;if(sentence&&state.pattern!=='all'&&x.pattern!==state.pattern)return false;if(!sentence&&state.filter.group!=='all'&&vocabularySection(x)!==state.filter.group)return false;if(!sentence&&!ignoreKana&&state.filter.kana&&state.filter.kana!=='all'&&hiraganaInitial(x)!==state.filter.kana)return false;const p=progress[sentence?'sentences':mode==='vocabulary-rebuild'?'vocabularyRebuild':mode==='kanji-writing'?'kanjiWriting':'words'][x.id];if(state.filter.status==='review')return !p||p.wins<2;if(state.filter.status==='new')return !p;return true;});}
function begin(mode,ids){if(!['write','vocabulary-rebuild','kanji-writing','sentences'].includes(mode))return;const items=(ids||shuffle(pool(mode).map(x=>x.id))).filter(id=>mode==='kanji-writing'?hasKanji(wordBy(id))&&wordGameReady(wordBy(id)):!['write','vocabulary-rebuild'].includes(mode)||VOCABULARY_WORD_IDS.has(id));state.round={mode,ids:items,index:0,correct:0,missed:[],revealed:false,checked:false,assisted:false,result:null,order:null,chosen:[],options:null,selected:null,b:'',c:'',hint:false};prepareQuestion();}
function prepareQuestion(){const r=state.round;if(!r||r.index>=r.ids.length)return;r.revealed=false;r.checked=false;r.luluFeedback=null;r.assisted=!!r.learningGuided;r.result=null;r.chosen=[];r.options=null;r.selected=null;r.b='';r.c='';r.hint=!!r.learningGuided;r.ink=[];if(r.mode==='sentences')r.order=shuffledTokens(sentenceBy(r.ids[r.index]));if(r.mode==='vocabulary-rebuild')r.tileBank=vocabularyTileBank(wordBy(r.ids[r.index]));}
function current(){return state.round?.ids[state.round.index];}
// Content no longer owns game progress; the app bar renders the shared tracker.
function roundBar(){return '';}
function gameProgress(){
 if(state.view==='mock'&&mock){const total=mock.a.length+mock.b.length,completed=mock.done?total:mock.a.filter(q=>q.b.trim()&&q.c.trim()).length+mock.b.filter(q=>q.chosen.length===sentenceBy(q.id).tokens.length).length;return {total,completed,current:completed};}
 const r=state.view==='number-game'?state.numberRound:state.view==='activity'?state.activity:state.round;
 if(!r?.ids?.length)return {total:0,completed:0,current:0};
 return {total:r.ids.length,completed:Math.min(r.ids.length,r.index+(r.checked?1:0)),current:Math.min(r.ids.length,r.index+1)};
}
function appBarCounter(){const p=gameProgress();return `<span class="game-round" aria-label="${esc(translateText('Round progress'))}">${p.current} / ${p.total}</span>`;}
function appBarProgress(){const p=gameProgress();return `<div class="game-progress" role="progressbar" aria-label="${esc(translateText('Completed rounds'))}" aria-valuemin="0" aria-valuemax="${p.total}" aria-valuenow="${p.completed}"><span style="width:${p.total?100*p.completed/p.total:0}%"></span></div>`;}
function updateAppBarProgress(){const p=gameProgress(),bar=document.querySelector('.game-progress'),counter=document.querySelector('.game-round');if(bar){bar.setAttribute('aria-valuenow',p.completed);const fill=bar.querySelector('span');if(fill)fill.style.width=`${p.total?100*p.completed/p.total:0}%`;}if(counter)counter.textContent=`${p.current} / ${p.total}`;}

function completeRound(ok){const r=state.round;if(ok)r.correct++;else if(!r.missed.includes(current()))r.missed.push(current());r.checked=true;luluGradeRound(r);}
function nextQuestion(){state.round.index++;prepareQuestion();render();}
function roundEnd(){const r=state.round;if(r.learningGuided)return `<section class="study-wrap paper">${luluSummaryArt(r)}<h1>${nL('Guided practice complete','引導練習完成')}</h1><p>${r.guidedCorrect||0}/${r.ids.length} ${nL('correct with guidance','在引導下答對')}</p><p>${nL('These attempts are kept separate from independent sentence successes. Try the same selection independently next.','本次練習與獨立完成句子的成績分開記錄。接下來可獨立練習同一範圍。')}</p><button class="button primary" data-learning-start="grammar-independent">${nL('Independent practice','獨立練習')}</button></section>`;return `<div class="study-wrap paper result-center">${luluSummaryArt(r)}<div class="eyebrow muted">Round complete</div><h2 style="margin:var(--space-4) 0">${r.missed.length?'Good practice. Let’s keep it going.':'A lovely clean sweep.'}</h2><div class="result-score" style="margin:var(--space-6) 0">${r.correct}<small> / ${r.ids.length}</small></div><p class="muted">${r.missed.length?`${r.missed.length} items are ready for another look.`:'Another successful recall will help these words stick.'}</p><div class="card-actions">${r.missed.length?button('Practise missed items','repeatMissed','coral'):''}${button('Start a new round','restart','primary')}</div></div>`;}
function noItems(){return `<div class="empty paper">${luluSectionArt('empty')}<h2>Nothing in this selection.</h2><p class="muted">Try another chapter or reset the filters.</p><div class="card-actions">${button('Show all items','resetFilters','primary')}</div></div>`;}
function practice(mode){
  if(!state.round||state.round.mode!==mode)begin(mode);
  const r=state.round,isWords=['write','vocabulary-rebuild','kanji-writing'].includes(mode),menu=`${wordModePrefix(mode)}-menu`;
  const meta={write:['Make it stick.','Chinese / English → Hiragana + kanji or X. Each answer is worth 0.5 marks.',selectedWordSet(mode)?.label||'Vocabulary Recall'],'kanji-writing':['Kanji Writing','Draw each kanji with a mouse, touch or pen. Reveal the model to check your attempt.',selectedWordSet(mode)?.label||'Kanji Writing'],'vocabulary-rebuild':['Vocabulary Rebuild','Build the hiragana reading using the correct tiles.',selectedWordSet(mode)?.label||'Vocabulary Rebuild'],sentences:['Piece it together.','Tap every tile in order, including punctuation. Tap a placed tile to return it to the bank.','Sentence rebuilding']}[mode];
  const vocabularyGame=['write','vocabulary-rebuild'].includes(mode);
  let html=vocabularyGame?`<h1 class="sr-only">${mode==='write'?'Vocabulary Recall':'Vocabulary Rebuild'}</h1>`:header(...meta);
  if(!r.ids.length)return html+noItems();
  if(r.index>=r.ids.length)return html+roundEnd();
  html+=`<section class="study-wrap">${roundBar()}${mode==='write'?writeCard():mode==='kanji-writing'?kanjiWritingCard():mode==='vocabulary-rebuild'?vocabularyRebuildCard():sentenceCard()}</section>`;
  return html;
}
function writeCard(){
 const w=wordBy(current()),r=state.round;
 const fields=[['b','Hiragana','Type hiragana'],['c','Kanji / X','Kanji, X or blank']];
 const inputs=fields.map(([key,label,placeholder])=>`<div><label class="field-label" for="answer-${key}">${label} <span class="muted">0.5 mark</span></label><input id="answer-${key}" class="input jp ${r.checked?(r.result[key+'Ok']?'correct':'wrong'):''}" lang="ja" autocomplete="off" autocapitalize="off" spellcheck="false" value="${esc(r[key])}" ${r.checked?'disabled':''} placeholder="${placeholder}" data-answer="${key}"></div>`).join('');
 const corrections=r.checked?fields.map(([key,label])=>`<div class="answer-result ${r.result[key+'Ok']?'correct-text':'wrong-text'}"><strong>${label}</strong> · ${r.result[key+'Ok']?'✓ 0.5 mark':'0 marks · Correct:'} <span class="jp">${key==='b'?esc(w.kana):w.c==='X'?'Blank or X':esc(w.c)}</span></div>`).join(''):'';
 return `<div class="paper">${vocabularyVisual(w)}<div class="eyebrow muted">${sourceTag(w)}</div><div class="write-prompt" style="margin-top:var(--space-5)">${esc(w.zh)}</div><p class="muted">${esc(w.en)}</p>${w.note&&['1-c2','1-c6','1-06'].includes(w.id)?`<p class="small muted" style="margin-top:var(--space-3)">${esc(learningWordNote(w))}</p>`:''}<div class="answer-grid">${inputs}</div><p class="small muted" style="margin-top:var(--space-3)">No kanji? Leave the written-form field blank or enter X.</p><div class="card-actions">${r.checked?button('Next word '+icon('arrow'),'next','primary'):button('Check both answers','checkWrite','primary')}</div>${r.checked?`<div class="feedback ${r.result.score===1?'':'bad'}">${luluFeedbackHeading(r)}<strong>${r.result.score} / 1 mark</strong>${corrections}<p>${r.result.score===1?'Both columns are correct.':r.result.score===.5?'One field is correct: 0.5 points.':'Read the two answers, then try this word again at the end of the round.'}</p>${w.jp!==w.kana?`<p>Book spelling: <span class="jp">${esc(w.jp)}</span>. Use hiragana for the reading.</p>`:''}${w.note?`<p>${esc(learningWordNote(w))}</p>`:''}</div>`:luluFeedbackPlaceholder()}<p class="small muted" style="text-align:center;margin-top:var(--space-4)">Use your Japanese keyboard. Enter checks both answers.</p></div>`;
}
function tiles(s,order,chosen,locked=false,mockIndex=null){const attrs=mockIndex===null?'':`data-mock-index="${mockIndex}"`;return `<div class="token-area ${chosen.length?'filled':''}" aria-label="Your sentence">${chosen.length?chosen.map((id,i)=>`<button class="tile jp" lang="ja" data-return="${i}" ${attrs} ${locked?'disabled':''} aria-label="Return ${esc(s.tokens[id])} to word bank">${esc(s.tokens[id])}</button>`).join(''):'<span class="empty-hint">Your sentence goes here. Tap a tile below.</span>'}</div><div class="token-bank" aria-label="Shuffled word bank">${order.map(id=>`<button class="tile jp" lang="ja" data-tile="${id}" ${attrs} ${locked||chosen.includes(id)?'disabled':''}>${esc(s.tokens[id])}</button>`).join('')}</div>`;}
function sentenceCard(){const r=state.round,s=sentenceBy(current()),p=patternBy(s.pattern);return `<div class="paper"><div class="row between"><span class="eyebrow muted">CHAPTER ${s.ch} · SENTENCE REBUILD</span><span class="chip">${status(s.id,'sentences')}</span></div><div class="sentence-prompt">${esc(s.prompt)}</div>${tiles(s,r.order,r.chosen,r.checked)}${r.hint?`<div class="hint">${luluSectionArt('grammar','lulu-small')}<strong>${esc(p.title)}</strong><div class="jp">${esc(p.formula)}</div><p>${esc(p.tip)}</p></div>`:''}${r.checked?`<div class="feedback ${r.result?'':'bad'}">${luluFeedbackHeading(r)}<strong>${r.result?(r.assisted?'Correct with help — try it unaided next time.':'That’s the right order. +2 / 2'):r.revealed?'Study the order, then try again later.':'Not quite — look at this order.'}</strong><div class="jp" lang="ja">${esc(s.tokens.join(''))}</div><p>${esc(p.tip)}</p></div>`:luluFeedbackPlaceholder()}<div class="card-actions">${r.checked?button('Next sentence '+icon('arrow'),'next','primary'):button('Clear','clearTiles','ghost')+button('Pattern hint','hint','ghost')+button('Check order','checkSentence','primary',r.chosen.length!==s.tokens.length?'disabled':'')}</div>${!r.checked?`<div style="text-align:center;margin-top:var(--space-4)"><button class="scope-link" data-action="revealSentence">Show answer & mark for review</button></div>`:''}</div>`;}
function patternReference(){return grammarPatternCards();}

function bankWordRow(w){return `<tr data-word-id="${w.id}"><td><strong>${esc(w.zh)}</strong><div class="muted">${esc(w.en)}</div><div class="muted" style="margin-top:var(--space-2)">${esc(sourceTag(w))}</div></td><td><span class="jp" lang="ja">${esc(w.kana)}</span>${w.jp!==w.kana?`<div class="muted">Book: <span class="jp" style="font-size:13px">${esc(w.jp)}</span></div>`:''}</td><td>${hasKanji(w)?`<span class="jp" lang="ja">${esc(w.c)}</span>${w.note?`<div class="muted" style="max-width:250px;margin-top:var(--space-2)">${esc(learningWordNote(w))}</div>`:''}`:''}</td><td><span class="status-badge ${status(w.id)==='Secure'?'learned':''}">${status(w.id)}</span></td></tr>`;}
function bankRows(){const term=state.search.toLowerCase();const words=pool('bank').filter(w=>[w.zh,w.en,w.jp,w.kana,w.c].some(s=>s.toLowerCase().includes(term)));const groups=VOCAB_CATEGORIES.map(category=>{const entries=words.filter(w=>vocabularySection(w)===category.id);return entries.length?`<tbody data-word-category="${category.id}"><tr class="word-category-row"><th colspan="4" scope="rowgroup"><div class="row between"><span>${esc(category.label)}</span><span class="category-count">${entries.length} forms</span></div></th></tr>${entries.map(bankWordRow).join('')}</tbody>`:'';}).join('');return `<div class="small muted" style="margin:var(--space-4) 0">${words.length} forms · a polite or bracketed alternative gets its own entry</div><div class="table-wrap"><table class="word-table"><thead><tr><th>Meaning</th><th>Hiragana</th><th>Kanji</th><th>Practice progress</th></tr></thead>${groups||'<tbody><tr><td colspan="4">No words match this search.</td></tr></tbody>'}</table></div>`;}
function bank(){return header('Every word, in one place.','Browse words by meaning and use. Kanji follow the supplied textbook pages.',`${WORDS.length} forms`)+filters()+`<div class="bank-top"><input class="input search" type="search" aria-label="Search words" data-search placeholder="Search a meaning, reading or kanji…" value="${esc(state.search)}">${button('Recall Vocabulary words','writeSelection','primary')}</div><div id="bank-rows">${bankRows()}</div>`;}
function writeSelection(){const term=state.search.toLowerCase(),ids=pool('write').filter(w=>[w.zh,w.en,w.jp,w.kana,w.c].some(s=>s.toLowerCase().includes(term))).map(w=>w.id);if(!ids.length){toast('No Vocabulary words in this selection. Try Dialogue or change the filters.');return;}startWriteWords(ids,'Selected words');}
function mockIntro(){return header('Timed practice','Practise vocabulary and sentence order. Your answers and the remaining time are saved.','Chapters 1–2 · 15 minutes')+`<section class="study-wrap paper">${luluSectionArt('mock')}<h2>20 points</h2><p>10 vocabulary questions · 10 points</p><p>5 sentence-order questions · 10 points</p><p>${nL('Each vocabulary reading and written form is worth 0.5 points. Each sentence is worth 2 points. Revisit answers before submission or until time runs out.','每個詞彙讀音與書寫形式各0.5分，每句2分。提交前或時間結束前可以修改答案。')}</p><div class="card-actions">${mock&&!mock.done?button('Resume timed practice','resumeMock','primary'):button('Start timed practice','startMock','primary')}</div></section>`;}

function startMock(){state.view='mock';const a=shuffle([1,2].flatMap(ch=>shuffle(WORDS.filter(w=>w.group==='core'&&!w.id.startsWith('csv-')&&inChapter(w,ch)&&wordGameReady(w))).slice(0,5))).map(w=>({id:w.id,b:'',c:''}));const groups=shuffle([...shuffle(PATTERNS.filter(p=>p.ch===1)).slice(0,2),...shuffle(PATTERNS.filter(p=>p.ch===2)).slice(0,3)]);const b=groups.map(p=>{const s=shuffle(SENTENCES.filter(x=>x.pattern===p.id))[0];return{id:s.id,order:shuffledTokens(s),chosen:[]};});const started=Date.now();mock={a,b,deadline:started+15*60*1000,started,done:false,tab:'a',confirm:false};save();render();}
function timeLeft(){return Math.max(0,Math.ceil((mock.deadline-Date.now())/1000));}
function formatTime(n){return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function mockQuiz(){if(!mock)return mockIntro();if(mock.done)return mockResult();const aDone=mock.a.filter(x=>x.b.trim()&&x.c.trim()).length,bDone=mock.b.filter(x=>x.chosen.length===sentenceBy(x.id).tokens.length).length;return header('One question at a time.','Your answers are saved as you go. The timer continues if you leave or reload this page.')+`<div class="lulu-timed-calm">${luluSectionArt('mock','lulu-small')}</div><div class="mock-top"><div class="mock-tabs"><button data-mock-tab="a" aria-pressed="${mock.tab==='a'}" class="${mock.tab==='a'?'active':''}">Vocabulary · ${aDone}/10</button><button data-mock-tab="b" aria-pressed="${mock.tab==='b'}" class="${mock.tab==='b'?'active':''}">Sentences · ${bDone}/5</button></div><div style="text-align:right"><div class="timer ${timeLeft()<60?'warn':''}" role="timer" aria-label="Time remaining">${formatTime(timeLeft())}</div><div class="small muted">TIME REMAINING</div></div></div><div class="study-wrap">${mock.tab==='a'?`<p class="small muted">Write hiragana and kanji / X. 0.5 points for each field.</p>${mock.a.map((q,i)=>{const w=wordBy(q.id);return `<section class="mock-question"><div class="mock-q-title">${i+1}. ${esc(w.zh)}</div><div class="small muted">${esc(w.en)}</div><div class="answer-grid"><div><label class="field-label" for="mock-b-${i}">Hiragana</label><input class="input jp" id="mock-b-${i}" data-mock-field="b" data-mock-index="${i}" value="${esc(q.b)}" lang="ja" autocomplete="off" autocapitalize="off" spellcheck="false"></div><div><label class="field-label" for="mock-c-${i}">Kanji / X</label><input class="input jp" id="mock-c-${i}" data-mock-field="c" data-mock-index="${i}" value="${esc(q.c)}" lang="ja" autocomplete="off" autocapitalize="off" spellcheck="false"></div></div></section>`;}).join('')}<div class="card-actions"><button class="button primary" data-mock-tab="b">Go to sentences ${icon('arrow')}</button></div>`:`<p class="small muted">Put every tile in order. 2 marks per correct sentence. Tap a placed tile to undo it.</p>${mock.b.map((q,i)=>{const s=sentenceBy(q.id);return `<section class="mock-question"><div class="eyebrow muted">QUESTION ${i+1} · 2 MARKS</div><div class="sentence-prompt">${esc(s.prompt)}</div>${tiles(s,q.order,q.chosen,false,i)}</section>`;}).join('')}`}<div style="margin-top:var(--space-4);border-top:1px solid var(--line);padding-top:var(--space-6)">${mock.confirm?`<div class="info-box">You have ${10-aDone} unfinished vocabulary questions and ${5-bDone} unfinished sentences. Submit now for your score, or keep working.</div><div class="card-actions">${button('Keep working','cancelSubmit','ghost')}${button('Submit quiz now','finishMock','coral')}</div>`:`<div class="card-actions">${button('Submit both parts','confirmSubmit','coral')}</div>`}</div></div>`;}
function finishMock(timedout=false){if(!mock||mock.done)return;mock.done=true;mock.timedout=timedout;mock.finished=Date.now();mock.aResults=mock.a.map(q=>{const result=gradeWord(wordBy(q.id),q.b,q.c);record('words',q.id,result.score===1);return result;});mock.bResults=mock.b.map(q=>{const ok=gradeSentence(sentenceBy(q.id),q.chosen);record('sentences',q.id,ok);return ok;});mock.aScore=mock.aResults.reduce((n,r)=>n+r.score,0);mock.bScore=mock.bResults.filter(Boolean).length*2;mock.score=mock.aScore+mock.bScore;luluCommitFeedback(mock,{key:'timed-result',correct:mock.score,total:20});progress.best=Math.max(progress.best||0,mock.score);save();state.view='mock';render();window.scrollTo({top:0,behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
function mockResult(){return header('Your practice paid off.','Review the details below, then give the missed items another go.','Timed practice complete')+`<div class="study-wrap"><div class="paper result-center">${luluFeedbackHeading(mock)}<div class="eyebrow muted">${mock.timedout?'TIME IS UP · ANSWERS SUBMITTED':'CHAPTERS 1–2 · YOUR RESULT'}</div><div class="result-score" style="margin:var(--space-6) 0">${mock.score}<small> / 20</small></div><p class="muted">${mock.score>=18?'You’re finding your rhythm. Keep the spelling precise.':mock.score>=12?'A solid foundation. A little focused revision will help.':'Now you know exactly what to practise next.'}</p><div class="result-breakdown"><div class="score-card"><strong>${mock.aScore} / 10</strong><span class="small">Vocabulary</span></div><div class="score-card"><strong>${mock.bScore} / 10</strong><span class="small">Sentence order</span></div></div><div class="card-actions">${button('Practise missed Vocabulary words','mockMissedWords','ghost')}${button('Review missed sentences','mockMissedSentences','ghost')}${button('New timed practice','newMock','primary')}</div></div><details class="details" open><summary>Vocabulary · every answer</summary>${mock.a.map((q,i)=>{const w=wordBy(q.id),r=mock.aResults[i];return `<div class="result-row"><div class="row between"><strong>${i+1}. ${esc(w.zh)} · ${esc(w.en)}</strong><span class="${r.score===1?'correct-text':'wrong-text'}">${r.score} / 1</span></div><div class="small muted" style="margin-top:var(--space-2)">YOUR READING <span class="jp ${r.bOk?'correct-text':'wrong-text'}">${esc(q.b)||'—'}</span> · YOUR WRITTEN FORM <span class="jp ${r.cOk?'correct-text':'wrong-text'}">${esc(q.c)||'—'}</span></div><div class="jp">${esc(w.kana)} · ${esc(w.c)}</div></div>`;}).join('')}</details><details class="details" open><summary>Sentences · every answer</summary>${mock.b.map((q,i)=>{const s=sentenceBy(q.id),ok=mock.bResults[i];return `<div class="result-row"><div class="row between"><strong>${i+1}. ${esc(s.prompt)}</strong><span class="${ok?'correct-text':'wrong-text'}">${ok?'2':'0'} / 2</span></div><div class="small muted" style="margin-top:var(--space-2)">YOUR ORDER</div><div class="jp ${ok?'correct-text':'wrong-text'}">${esc(q.chosen.map(x=>s.tokens[x]).join(''))||'—'}</div><div class="small muted" style="margin-top:var(--space-2)">CORRECT ORDER</div><div class="jp">${esc(s.tokens.join(''))}</div><p>${esc(patternBy(s.pattern).tip)}</p></div>`;}).join('')}</details></div>`;}
let renderedView=null;

function render(){
  // Keep keyboard focus when an answer or language change redraws the app.
  const chipSelectors=['.number-mode-row','.number-filter-row','.vocabulary-mode-row','.vocabulary-filter-row','.dialogue-mode-row','.dialogue-filter-row','.expression-chip-row'];
  const previousLanguage=document.documentElement?.lang||state.language;
  for(const selector of chipSelectors){const row=$(selector);if(row)chipScrollPositions.set(`${selector}:${row.dataset.chipGroup||''}:${previousLanguage}`,row.scrollLeft);}
  const active=document.activeElement;
  const focusId=active?.id;
  const focusAttribute=active?.getAttributeNames?.().find(name=>name.startsWith('data-'));
  const focusValue=focusAttribute?active.getAttribute(focusAttribute):null;
  const selection=active?.tagName==='INPUT'?[active.selectionStart,active.selectionEnd]:null;
  const changedView=renderedView!==null&&renderedView!==state.view;
  renderedView=state.view;
  const previousNav=document.querySelector('.overview-nav')||document.querySelector('.sidebar .nav');const navScroll=previousNav?.scrollLeft||0;const page=state.view==='grammar'?grammarMenu():state.view==='pictures'?picturesMenu():state.view==='mixed'?mixedMenu():state.view==='exam-practice'?exPage():state.view==='number-menu'?numberMenu():state.view==='number-game'?numberGame():state.view==='home'?home():state.view==='bank'?learningVocabulary('reference'):state.view==='mock'?mockQuiz():state.view==='mock-menu'?mockIntro():state.view==='sentence-menu'?grammarMenu():state.view==='write-menu'?writeMenu():state.view==='vocabulary-menu'?vocabularyMenu():state.view==='vocabulary-content'?vocabularyContent():state.view==='handwriting-menu'?learningVocabulary('handwriting'):state.view==='demonstratives-content'?picturesMenu():state.view==='dialogue'?picturesMenu():state.view==='dialogue-content'?picturesMenu():state.view==='activity'?activityPage():practice(state.view);if(document.documentElement)document.documentElement.lang=state.language;$('#app').innerHTML=localizeMarkup(shell(page));luluAfterRender();const currentNav=document.querySelector('.overview-nav')||document.querySelector('.sidebar .nav');if(currentNav)currentNav.scrollLeft=navScroll;for(const selector of chipSelectors){const row=$(selector);if(row){const key=`${selector}:${row.dataset.chipGroup||''}`;row.scrollLeft=chipScrollPositions.get(`${key}:${state.language}`)??chipScrollPositions.get(`${key}:${previousLanguage}`)??0;}}if(state.modal)setTimeout(()=>$('.modal button')?.focus(),0);
  else if(state.navOpen)setTimeout(()=>$('.drawer-close')?.focus(),0);
  else if(changedView)$('#main-content')?.focus({preventScroll:true});
  else {
    const focusTarget=focusId?document.getElementById?.(focusId):focusAttribute?[...document.querySelectorAll(`[${focusAttribute}]`)].find(el=>el.getAttribute(focusAttribute)===focusValue):null;
    if(focusTarget&&!focusTarget.disabled){if(focusTarget.dataset?.filterChip)focusFilterChip(focusTarget);focusTarget.focus({preventScroll:true});if(selection&&selection[0]!==null)focusTarget.setSelectionRange?.(...selection);}
  }
}

function navigate(view,remember=true){state.learningReturn=null;view=({dialogue:'pictures','dialogue-content':'pictures','demonstratives-content':'pictures','sentence-menu':'grammar',sentences:'grammar','exam-practice':'mixed','all-words':'bank','word-reference':'bank','timed-practice':'mock','mixed-practice':'mixed'})[view]||view;if(['write-menu','cards'].includes(view))view='vocabulary-menu';if(remember)rememberPage();state.view=view==='rebuild-menu'?'home':['matching','match','kanji-menu','hiragana-menu','hiragana-match'].includes(view)?'vocabulary-menu':view==='hiragana'?'home':view==='cards'?'write-menu':view;state.modal=false;state.navOpen=false;state.round=null;if(state.view==='write-menu')state.writeMenu='main';if(state.view==='vocabulary-menu')state.vocabularyMenu='main';if(state.view==='handwriting-menu')state.handwritingMenu='main';render();window.scrollTo({top:0,behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
function resetFilters(){state.filter={ch:['all'],group:'all',status:'all',kana:'all'};state.pattern='all';state.round=null;}
function run(action){if(action.startsWith('vocabulary')){vocabularyAction(action);return;}if(action.startsWith('kanji')){kanjiWritingAction(action);return;}const r=state.round;switch(action){case'openNavigation':state.navOpen=true;render();break;case'closeNavigation':state.navOpen=false;render();$('.menu-button')?.focus();break;case'back':previousPage();break;case'gameBack':gameBack();break;case'startSentences':state.view='sentences';begin('sentences');render();break;case'resumeMock':state.view='mock';render();break;case'toggleLanguage':state.language=state.language==='zh-Hant'?'en':'zh-Hant';save();render();break;case'writeSelection':writeSelection();break;case'scope':state.navOpen=false;state.modal=true;render();break;case'closeScope':state.modal=false;render();$('.footer-line [data-action="scope"]')?.focus();break;case'closeBackdrop':break;case'checkWrite':if(!r.checked){r.result=gradeWord(wordBy(current()),r.b,r.c,true);record('words',current(),r.result.score===1);completeRound(r.result.score===1);render();}break;case'next':nextQuestion();break;case'restart':begin(state.view,selectedWordSet(state.view)?shuffle(selectedWordSet(state.view).ids):undefined);render();break;case'repeatMissed':begin(state.view,shuffle(r.missed));render();break;case'resetFilters':resetFilters();render();break;case'clearTiles':r.chosen=[];render();break;case'hint':r.hint=true;r.assisted=true;render();break;case'checkSentence':if(!r.checked){r.result=gradeSentence(sentenceBy(current()),r.chosen);if(r.result&&r.assisted)r.guidedCorrect=(r.guidedCorrect||0)+1;record('sentences',current(),r.result&&!r.assisted);completeRound(r.result&&!r.assisted);render();}break;case'revealSentence':if(!r.checked){r.revealed=true;r.result=false;r.assisted=true;record('sentences',current(),false);completeRound(false);render();}break;case'startMock':startMock();break;case'newMock':mock=null;save();render();break;case'confirmSubmit':mock.confirm=true;render();break;case'cancelSubmit':mock.confirm=false;render();break;case'finishMock':finishMock();break;case'mockMissedWords':{const missed=mock.a.filter((q,i)=>mock.aResults[i].score<1).map(q=>q.id),ids=missed.filter(id=>VOCABULARY_WORD_IDS.has(id));if(!ids.length){toast(missed.length?'These missed words are practised in Dialogue.':'All vocabulary answers were correct.');break;}resetFilters();startWriteWords(ids,'Missed words');break;}case'mockMissedSentences':{const ids=mock.b.filter((q,i)=>!mock.bResults[i]).map(q=>q.id);if(!ids.length){toast('All sentence orders were correct.');break;}resetFilters();state.view='sentences';begin('sentences',ids);render();window.scrollTo({top:0,behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});break;}}}
document.addEventListener('click',e=>{const target=e.target.closest('button,[data-action]');if(!target||target.disabled)return;if(target.dataset.crumbView){navigateBreadcrumb(target.dataset);return;}if(numberClick(target.dataset))return;if(activityClick(target))return;if(target.dataset.vocabularyBrowse){vocabularyBrowse(target.dataset.vocabularyBrowse);return;}if(target.dataset.vocabularyPractice){startVocabularyPractice(target.dataset.vocabularyPractice);return;}if(target.dataset.handwritingMenu){openWordMenu('handwriting',target.dataset.handwritingMenu);return;}if(target.dataset.handwritingSet){startWordSet('kanji-writing',target.dataset.handwritingSet);return;}if(target.dataset.vocabularyMenu){openWordMenu('vocabulary',target.dataset.vocabularyMenu);return;}if(target.dataset.vocabularySet){openVocabularyContent(target.dataset.vocabularySet);return;}if(target.dataset.writeMenu){openWordMenu('write',target.dataset.writeMenu);return;}if(target.dataset.writeSet){startWriteSet(target.dataset.writeSet);return;}if(target.dataset.vocabularyTile!==undefined||target.dataset.vocabularyReturn!==undefined){vocabularyTileClick(target.dataset);return;}if(target.dataset.view){navigate(target.dataset.view);return;}if(target.dataset.action){if(target.dataset.action==='closeBackdrop'){if(e.target===target)run('closeScope');return;}run(target.dataset.action);return;}if(target.dataset.tile!==undefined||target.dataset.return!==undefined){const isMock=target.dataset.mockIndex!==undefined;const q=isMock?mock.b[Number(target.dataset.mockIndex)]:state.round;if((isMock&&mock.done)||(!isMock&&q.checked))return;if(target.dataset.tile!==undefined){const id=Number(target.dataset.tile);if(!q.chosen.includes(id))q.chosen.push(id);}else q.chosen.splice(Number(target.dataset.return),1);if(isMock){save();const y=window.scrollY;render();window.scrollTo(0,y);}else render();return;}if(target.dataset.startPattern){state.pattern=target.dataset.startPattern;state.filter.status='all';state.view='sentences';begin('sentences');render();window.scrollTo({top:0,behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});return;}if(target.dataset.mockTab){mock.tab=target.dataset.mockTab;save();render();window.scrollTo({top:0,behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.answer)state.round[t.dataset.answer]=t.value;if(t.dataset.mockField){mock.a[Number(t.dataset.mockIndex)][t.dataset.mockField]=t.value;save();const count=mock.a.filter(q=>q.b.trim()&&q.c.trim()).length;const tab=$('[data-mock-tab="a"]');if(tab)tab.textContent=translateText(`Vocabulary · ${count}/10`);updateAppBarProgress();}if(t.hasAttribute('data-search')){state.search=t.value;$('#bank-rows').innerHTML=localizeMarkup(bankRows());}});
document.addEventListener('change',e=>{const t=e.target;if(t.hasAttribute('data-vocabulary-select')){openVocabularyContent(t.value);return;}if(t.dataset.filter){state.filter[t.dataset.filter]=t.value;state.round=null;render();}if(t.hasAttribute('data-pattern')){state.pattern=t.value;state.round=null;render();}});
function revealDialogueChip(chip){
  const row=chip.parentElement,edge=row.getBoundingClientRect(),item=chip.getBoundingClientRect();
  if(item.left<edge.left)row.scrollLeft+=item.left-edge.left;
  else if(item.right>edge.right)row.scrollLeft+=item.right-edge.right;
}
document.addEventListener('focusin',e=>{const chip=e.target.closest?.('[data-dialogue-browse],[data-dialogue-chapter],[data-dialogue-category],[data-dialogue-expression],[data-wh-expression],[data-vocabulary-browse],[data-vocabulary-set],[data-number-browse],[data-number-type],[data-number-chapter]');if(chip)revealDialogueChip(chip);});
document.addEventListener('keydown',e=>{if(e.isComposing)return;const chip=e.target.closest?.('[data-dialogue-browse],[data-dialogue-chapter],[data-dialogue-category],[data-dialogue-expression],[data-wh-expression],[data-vocabulary-browse],[data-vocabulary-set],[data-number-browse],[data-number-type],[data-number-chapter]');if(chip&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){const chips=[...chip.parentElement.querySelectorAll('.dialogue-chip')],index=chips.indexOf(chip),next=e.key==='Home'?chips[0]:e.key==='End'?chips.at(-1):chips[(index+(e.key==='ArrowRight'?1:-1)+chips.length)%chips.length];e.preventDefault();next.focus({preventScroll:true});revealDialogueChip(next);return;}if(state.navOpen){if(e.key==='Escape'){e.preventDefault();run('closeNavigation');}else if(e.key==='Tab'){const controls=[...document.querySelectorAll('.sidebar button')].filter(el=>el.getClientRects().length),first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}return;}if(e.key==='Escape'&&state.modal){run('closeScope');return;}if(state.modal&&e.key==='Tab'){const focusable=[...document.querySelectorAll('.modal button')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}return;}if(state.modal)return;if(state.view==='number-game'&&!['INPUT','TEXTAREA','SELECT','BUTTON','A'].includes(e.target.tagName)){const r=state.numberRound;if(r&&r.index<r.ids.length){if(e.key==='Enter'){e.preventDefault();if(r.checked)numberClick({action:'numberNext'});else if(numberAnswerReady())checkNumberMatching();}else if(e.key==='Backspace'&&!r.checked){e.preventDefault();numberClick({action:'numberUndo'});}return;}}if(state.view==='activity'&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){const a=state.activity;if(a&&a.index<a.ids.length){if(e.key==='Enter'&&!['BUTTON','A'].includes(e.target.tagName)){e.preventDefault();if(a.checked)activityAction('activityNext');else if((isActivityRebuild(a)&&activityReady(activityCurrent()))||activityCurrent().forms&&a.selections.length===2)checkActivity();}else if(e.key==='Backspace'&&isActivityRebuild(a)&&!a.checked){e.preventDefault();activityAction('activityUndo');}else if(/^[1-4]$/.test(e.key)&&!a.checked&&!isActivityRebuild(a)){e.preventDefault();selectActivityChoice(a.choices[Number(e.key)-1]?.id);}return;}}const isInput=['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName);if(isInput){if(e.key==='Enter'&&state.view==='write'&&!state.round.checked){e.preventDefault();run('checkWrite');}return;}const r=state.round;if(!r||r.index>=r.ids.length)return;if(state.view==='vocabulary-rebuild'&&!r.checked){if(e.key==='Backspace'){e.preventDefault();vocabularyAction('vocabularyUndo');}else if(e.key==='Enter'&&!['BUTTON','A'].includes(e.target.tagName)){e.preventDefault();vocabularyAction('vocabularyCheck');return;}}if(e.key==='Enter'&&r.checked&&!['BUTTON','A'].includes(e.target.tagName)){e.preventDefault();run('next');}});
setInterval(()=>{if(mock&&!mock.done){const time=timeLeft(),el=$('.timer');if(el){el.textContent=formatTime(time);el.classList.toggle('warn',time<60);}if(time===0)finishMock(true);}},1000);
for(const key of ['vocabulary','reference','handwriting','grammar','pictures'])if(state.learningScopes[key])normalizeLearningScope(key);
state.filter.ch=normalizeChapters(state.filter.ch);
if(saved.learningSchema!==3)save();
